"use client";
import type { ComponentProps } from "react";
import { cx } from "@/lib/cx";
/** Shared label paint for stand-alone indicators and conversation authors. */
export function AgentThinkingLabel({
  shimmer = true,
  variant = "conversation",
  className,
  ...props
}: ComponentProps<"span"> & { shimmer?: boolean; variant?: "conversation" | "progress" }) {
  return (
    <span
      {...props}
      className={cx(
        shimmer &&
          (variant === "progress" ? "agent-progress-loading-text" : "bui-agent-thinking-label"),
        className,
      )}
    />
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { IconButton } from "../../base/buttons/icon-button";
import { cx } from "@/lib/cx";

export type ComposerAttachmentKind = "image" | "document" | "spreadsheet" | "presentation" | "code" | "video";
export interface ComposerAttachment {
  id: string;
  name: string;
  kind: ComposerAttachmentKind;
  src?: string;
  /** Omit for a landed file; values below 100 show upload progress. */
  progress?: number;
}
export interface ComposerAttachmentTileProps {
  attachment: ComposerAttachment;
  onRemove?: () => void;
  className?: string;
}
const assets: Record<Exclude<ComposerAttachmentKind, "image">, string> = {
  document: "/ai-chat/plugin-documents.svg", spreadsheet: "/ai-chat/plugin-spreadsheets.svg", presentation: "/ai-chat/plugin-presentations.svg", code: "/ai-chat/plugin-codeblocks.svg", video: "/ai-chat/plugin-videos.svg",
};
function DismissIcon({ className }: { className?: string }) {
  return <svg className={className} style={{ width: 6.8, height: 6.8 }} viewBox="0 0 6.8 6.8" fill="none" aria-hidden>
    <path d="M.57 .57 6.23 6.23" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
    <path d="M6.23 .57.57 6.23" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
  </svg>;
}
export function ComposerAttachmentTile({ attachment, onRemove, className }: ComposerAttachmentTileProps) {
  const progress = Math.min(100, Math.max(0, Number.isFinite(attachment.progress) ? attachment.progress! : 100));
  const uploading = progress < 100, image = attachment.kind === "image";
  return <div title={attachment.name} className={cx("relative size-14 shrink-0 rounded-xl border border-composer-panel-tile-border", className)}>
    {image ? <img src={attachment.src} alt={attachment.name} className={cx("absolute inset-0 size-full rounded-[11px] object-cover transition-opacity duration-300 ease-out", uploading && "opacity-60")} /> :
      <div className={cx("transition-opacity duration-300 ease-out", uploading && "opacity-60")}>
        <img src={assets[attachment.kind === "image" ? "document" : attachment.kind]} alt="" aria-hidden className={cx("absolute start-[3px] top-1 size-6", attachment.kind === "document" && "theme-asset-light")} />
        {attachment.kind === "document" && <img src="/ai-chat/plugin-documents-dark.svg" alt="" aria-hidden className="theme-asset-dark absolute start-[3px] top-1 size-6" />}
        <span className="absolute start-1.5 top-9 max-w-[44px] truncate text-[9px] font-medium leading-[15px] tracking-[0.2px] text-text-secondary">{attachment.name}</span>
      </div>}
    <svg aria-hidden viewBox="0 0 56 56" className={cx("pointer-events-none absolute -inset-px size-14 transition-opacity duration-300 ease-out", uploading ? "opacity-100" : "opacity-0")}>
      <path d="M28 1H44A11 11 0 0 1 55 12V44A11 11 0 0 1 44 55H12A11 11 0 0 1 1 44V12A11 11 0 0 1 12 1Z" fill="none" stroke="var(--color-accent-400)" strokeWidth="2" strokeLinecap="round" pathLength="100" strokeDasharray={`${progress >= 100 ? 102 : progress} 200`} className="transition-[stroke-dasharray] duration-200 ease-linear" />
    </svg>
    <span aria-hidden className={cx("absolute end-[3px] top-[3px] text-[9px] font-medium leading-4 tabular-nums transition-[opacity,filter] duration-300 ease-out", image ? "text-text-white" : "text-accent-500", uploading ? "opacity-100 blur-[0px]" : "pointer-events-none opacity-0 blur-[3px]")}>{Math.round(progress)}%</span>
    {onRemove && <IconButton unstyled icon={DismissIcon} aria-label={`Remove ${attachment.name}`} onClick={onRemove} disabled={uploading} className={cx("absolute start-[35px] top-[3px] inline-flex size-4 shrink-0 cursor-pointer select-none items-center justify-center rounded-full outline-none transition-[opacity,filter,color] duration-300 ease-out focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2", image ? "bg-white/50 text-text-white backdrop-blur-[2px] hover:text-text-white" : "bg-background-tertiary-default/50 text-foreground-icon-secondary hover:text-text-primary", uploading ? "pointer-events-none opacity-0 blur-[3px]" : "opacity-100 blur-[0px]")} />}
  </div>;
}
export interface ComposerAttachmentStripProps {
  attachments: readonly ComposerAttachment[];
  onRemove?: (id: string) => void;
  className?: string;
}
export function ComposerAttachmentStrip({ attachments, onRemove, className }: ComposerAttachmentStripProps) {
  return <AnimatePresence initial={false}>{attachments.length > 0 &&
    <motion.div key="attachments" initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: .28, ease: [.22, 1, .36, 1] }} className="overflow-hidden">
      <div className={cx("flex flex-wrap items-start gap-2 pb-1", className)}>
        <AnimatePresence>{attachments.map(attachment => <motion.div key={attachment.id} initial={{ opacity: 0, scale: .8, filter: "blur(4px)" }} animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }} exit={{ opacity: 0, scale: .8, filter: "blur(4px)" }} transition={{ duration: .28, ease: [.22, 1, .36, 1] }}>
          <ComposerAttachmentTile attachment={attachment} onRemove={onRemove ? () => onRemove(attachment.id) : undefined} />
        </motion.div>)}</AnimatePresence>
      </div>
    </motion.div>}
  </AnimatePresence>;
}

"use client";
import { ComposerPanel as SharedComposerPanel, type ComposerPanelProps } from "./composer";
export type { ComposerPanelProps } from "./composer";
/** Standalone registry entry for the shared composer panel. */
export function ComposerPanel(props: ComposerPanelProps = {}) {
  return <SharedComposerPanel {...props} />;
}

// @zeus-internal
import type { ModelProvider } from "./model-picker";
import type { ComposerModel } from "./composer";

// Illustrative groups; applications supply their own provider catalogue.
const COUNTS = [12, 10, 8, 8, 10, 9, 9, 10, 10, 9, 10, 9, 9, 9, 9, 8, 9, 9];
const DEFAULT_PROVIDERS = COUNTS.map((count, index) => ({
  id: `provider-${index + 1}`,
  label: `Provider ${index + 1}`,
  models: Array.from({ length: count }, (_, model) => ({ id: `provider-${index + 1}-model-${model + 1}`, label: `Model ${index + 1}.${model + 1}` })),
}));
DEFAULT_PROVIDERS[0]!.models[0] = { id: "compact-model", label: "Compact model" };
DEFAULT_PROVIDERS[0]!.models[2] = { id: "gpt-5.6-sol", label: "Model 2" };
DEFAULT_PROVIDERS[1]!.models[1] = { id: "fable-5", label: "Model 3" };
DEFAULT_PROVIDERS[1]!.models[3] = { id: "sonnet-5", label: "Model 4" };
DEFAULT_PROVIDERS[3]!.models[0] = { id: "composer-2.5", label: "Model 1" };

export function composerProviders(models?: ComposerModel[]): readonly ModelProvider[] {
  return models ? [{ id: "custom-models", label: "Models", models }] : DEFAULT_PROVIDERS;
}

import { RiFolder2Line, RiGitMergeLine } from "@remixicon/react";
import { cx } from "@/lib/cx";
import { ContextMeter } from "./context-meter";
export interface ComposerStatusTabProps {
  branch?: string;
  project?: string;
  contextPercent?: number;
  className?: string;
}
/** Passive branch/project metadata in the composer's inset status tab. */
export function ComposerStatusTab({ branch = "Main", project = "app", contextPercent = 57, className }: ComposerStatusTabProps = {}) {
  return <div className={cx("mx-7 flex h-[34px] items-center justify-between gap-3 rounded-t-2xl bg-composer-panel-tab-background px-2 py-1", className)}>
    <div className="flex min-w-0 items-center gap-3">
      <span className="flex min-w-0 items-center gap-1"><RiGitMergeLine aria-hidden className="size-4 shrink-0 -scale-y-100 text-foreground-icon-secondary" /><span className="truncate text-body-2-medium whitespace-nowrap text-text-secondary">{branch}</span></span>
      <span className="flex min-w-0 items-center gap-1"><RiFolder2Line aria-hidden className="size-4 shrink-0 text-foreground-icon-secondary" /><span className="truncate text-body-2-medium whitespace-nowrap text-text-secondary">{project}</span></span>
    </div>
    <ContextMeter appearance="plain" percent={contextPercent} />
  </div>;
}

import { cx } from "@/lib/cx";
export interface ContextMeterProps {
  percent?: number;
  appearance?: "badge" | "plain";
  className?: string;
}
/** Context usage shared by composer status bars and tabs. */
export function ContextMeter({ percent: value = 57, appearance = "badge", className }: ContextMeterProps) {
  const percent = Math.max(0, Math.min(100, value)), circumference = 2 * Math.PI * 6;
  return <span aria-label={`Context window ${percent}% used`} title={appearance === "badge" ? `${percent}% of the context window used` : undefined}
    className={cx("flex shrink-0 items-center gap-1 py-1 pe-2 ps-1.5", appearance === "badge" ? "rounded-full bg-background-tertiary-default" : "rounded-[40px]", className)}>
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className="shrink-0 -rotate-90" aria-hidden>
      <circle cx="8" cy="8" r="6" stroke="var(--color-neutral-300)" strokeWidth="2.5" />
      <circle cx="8" cy="8" r="6" stroke="var(--color-neutral-500)" strokeWidth="2.5"
        strokeDasharray={`${percent / 100 * circumference} ${circumference}`} strokeLinecap="round" />
    </svg>
    <span className="text-body-2-medium whitespace-nowrap text-text-secondary">{Math.round(percent)}%</span>
  </span>;
}

"use client";
import { useEffect, useRef, useState, type ComponentType } from "react";
import { RiArrowDownSLine, RiCpuLine, RiSearchLine } from "@remixicon/react";
import { Button } from "../../base/buttons/button";
import { Dropdown, DropdownPopover, DropdownTrigger } from "../../base/dropdown/dropdown";
import { InputBase, TextField } from "../../base/input/input";
import { RadioDot } from "../../base/radio/radio";
import { VerticalScroll } from "../../base/scroll-area/vertical-scroll";
import { EffortControl } from "../../base/slider/effort-control";
import { cx } from "@/lib/cx";
import type { ComposerModel } from "./composer";

export interface ModelProvider {
  id: string;
  label: string;
  icon?: ComponentType<{ className?: string }>;
  models: readonly ComposerModel[];
}
export interface ModelPickerProps {
  providers: readonly ModelProvider[];
  value: string;
  onChange: (model: string) => void;
  effort: number;
  onEffortChange: (effort: number) => void;
  className?: string;
}
const EFFORT_LABELS = ["Low", "Medium", "Balanced", "High", "Very High", "Max"];

/** Provider browsing and cross-provider model search with a nested effort control. */
export function ModelPicker({ providers, value, onChange, effort, onEffortChange, className }: ModelPickerProps) {
  const selectedProvider = providers.find(provider => provider.models.some(model => model.id === value));
  const selectedModel = selectedProvider?.models.find(model => model.id === value);
  const [isOpen, setOpen] = useState(false);
  const [providerId, setProviderId] = useState(selectedProvider?.id ?? providers[0]?.id);
  const [searching, setSearching] = useState(false);
  const [query, setQuery] = useState("");
  const scrollRef = useRef<HTMLDivElement>(null);
  const providerRefs = useRef(new Map<string, HTMLButtonElement>());
  const focusFrame = useRef<number | null>(null);
  const activeProvider = providers.find(provider => provider.id === providerId) ?? selectedProvider ?? providers[0];
  const selectedProviderId = selectedProvider?.id;
  const selectedEffort = Number.isFinite(effort) ? Math.max(0, Math.min(5, Math.round(effort))) : 1;
  useEffect(() => { if (selectedProviderId) setProviderId(selectedProviderId); }, [selectedProviderId]);
  useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = 0; }, [activeProvider?.id, query, searching]);
  useEffect(() => () => { if (focusFrame.current !== null) cancelAnimationFrame(focusFrame.current); }, []);
  const closeSearch = () => {
    setQuery("");
    setSearching(false);
    if (focusFrame.current !== null) cancelAnimationFrame(focusFrame.current);
    focusFrame.current = requestAnimationFrame(() => {
      focusFrame.current = null;
      const first = providers[0];
      if (first) providerRefs.current.get(first.id)?.focus();
    });
  };
  useEffect(() => {
    if (!isOpen) return;
    const handleKey = (event: KeyboardEvent) => {
      const target = event.target instanceof Element ? event.target : null;
      if (target?.closest('[role="dialog"][aria-label="Effort"]')) return;
      if (event.key === "Escape" && searching) {
        event.preventDefault();
        event.stopImmediatePropagation();
        if (query) setQuery("");
        else closeSearch();
      } else if (event.key === "/" && !target?.closest('input,textarea,[contenteditable="true"]')) {
        event.preventDefault();
        event.stopImmediatePropagation();
        setSearching(true);
      }
    };
    document.addEventListener("keydown", handleKey, true);
    return () => document.removeEventListener("keydown", handleKey, true);
  });
  const results = searching
    ? providers.flatMap(provider => provider.models
      .filter(model => `${provider.label} ${model.label}`.toLowerCase().includes(query.trim().toLowerCase()))
      .map(model => ({ provider, model })))
    : (activeProvider?.models ?? []).map(model => ({ provider: activeProvider!, model }));
  return <Dropdown isOpen={isOpen} onOpenChange={next => {
    setOpen(next);
    if (!next) { setSearching(false); setQuery(""); }
  }}>
    <DropdownTrigger aria-label={`Select model: ${selectedModel?.label ?? "Select model"}`}
      isDisabled={!providers.some(provider => provider.models.length)}
      className={cx("flex h-8 shrink-0 items-center justify-center gap-0.5 rounded-xl bg-background-primary-default py-1.5 pe-1 ps-2 outline-none transition-colors duration-150 ease hover:bg-background-primary-hover", className)}>
      <span className="px-0.5 text-body-medium whitespace-nowrap text-text-secondary">{selectedModel?.label ?? "Select model"}</span>
      <RiArrowDownSLine aria-hidden className={cx("size-[18px] shrink-0 text-foreground-icon-secondary transition-transform duration-200 ease", isOpen && "rotate-180")} />
    </DropdownTrigger>
    <DropdownPopover aria-label="Models" placement="top start" offset={8}
      className="relative h-[282px] w-[341px] overflow-clip rounded-[20px] p-0 shadow-model-picker"
      dialogClassName="block size-full">
      <div role="tablist" aria-label="Providers" aria-orientation="vertical"
        className="absolute top-0.5 start-0.5 h-[276px] w-[42px] overflow-y-auto rounded-[17px] bg-composer-panel-rail-background p-[3px] [scrollbar-width:none]">
        <div className="flex w-9 flex-col gap-1.5">
          {providers.map(provider => {
            const Icon = provider.icon ?? RiCpuLine;
            return <Button key={provider.id} unstyled role="tab" aria-selected={activeProvider?.id === provider.id}
              aria-label={provider.label} title={provider.label}
              ref={element => { if (element) providerRefs.current.set(provider.id, element); else providerRefs.current.delete(provider.id); }}
              onClick={() => { setProviderId(provider.id); setSearching(false); setQuery(""); }}
              className={cx("flex h-[30px] w-9 shrink-0 cursor-pointer items-center justify-center rounded-[50px] outline-none transition-colors duration-150 ease focus-visible:ring-2 focus-visible:ring-border-focus-ring", activeProvider?.id === provider.id ? "bg-background-tertiary-default" : "hover:bg-background-tertiary-default/50")}>
              <Icon className="size-5 shrink-0 text-foreground-icon-secondary" />
            </Button>;
          })}
        </div>
      </div>
      <div className="absolute top-2 end-2 bottom-0 start-[52px] flex flex-col">
        <div className="flex h-5 items-center justify-between gap-[5px] px-0.5">
          {searching ? <>
            <TextField aria-label="Search models" value={query} onChange={setQuery} className="min-w-0 flex-1">
              <InputBase autoFocus placeholder="Search models"
                fieldClassName="rounded-none bg-transparent p-0 ring-0 focus-within:ring-0 shadow-none"
                className="h-5 pl-0 text-body-medium caret-accent-500 focus:placeholder:text-text-tertiary" />
            </TextField>
            <Button unstyled aria-label="Close search" onClick={closeSearch}
              className="flex shrink-0 cursor-pointer items-center rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring">
              <RiSearchLine aria-hidden className="size-4 shrink-0 text-foreground-icon-secondary" />
            </Button>
          </> : <>
            <span className="text-body-medium text-text-tertiary">Models</span>
            <Button unstyled aria-label="Quick search" onClick={() => setSearching(true)}
              className="flex shrink-0 cursor-pointer items-center gap-[5px] rounded-sm opacity-50 outline-none transition-opacity duration-150 hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-border-focus-ring">
              <span className="text-body-medium whitespace-nowrap text-text-secondary">Quick Search</span>
              <RiSearchLine aria-hidden className="size-4 shrink-0 text-foreground-icon-secondary" />
            </Button>
          </>}
        </div>
        <VerticalScroll variant="model-picker" scrollRef={scrollRef} role="radiogroup" tabIndex={-1}
          aria-label={searching ? "Matching models" : `${activeProvider?.label ?? "Available"} models`}
          className="mt-1 flex min-h-0 flex-1 flex-col" scrollClassName="flex min-h-0 flex-1 flex-col gap-1 pb-1">
          {results.map(({ provider, model }) => {
            const checked = value === model.id;
            const Icon = provider.icon ?? RiCpuLine;
            return <div key={`${provider.id}:${model.id}`}
              className={cx("relative flex h-9 w-full shrink-0 items-center gap-3 rounded-2lg px-2 transition-colors duration-150", checked ? "bg-background-primary-hover" : "hover:bg-background-primary-hover")}>
              <Button unstyled role="radio" aria-checked={checked} aria-label={`${provider.label} ${model.label}`}
                onClick={() => { onChange(model.id); if (searching) { setProviderId(provider.id); setSearching(false); setQuery(""); } }}
                className="absolute inset-0 cursor-pointer rounded-2lg outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring" />
              <span className="pointer-events-none flex min-w-0 flex-1 items-center gap-3">
                <span className="flex min-w-0 flex-1 items-center gap-1.5">
                  <Icon className="size-4 shrink-0 text-foreground-icon-secondary" />
                  <span className="min-w-0 flex-1 truncate text-body-medium whitespace-nowrap"><span className="text-text-primary">{model.label}</span>{searching && <span className="ms-1.5 text-text-tertiary">{provider.label}</span>}</span>
                  {checked && <EffortPicker value={selectedEffort} onChange={onEffortChange} />}
                </span>
              </span>
              <RadioDot selected={checked} size="sm" className="pointer-events-none" />
            </div>;
          })}
          {!results.length && <p className="px-2 py-2 text-body-medium text-text-tertiary">No models match</p>}
        </VerticalScroll>
      </div>
    </DropdownPopover>
  </Dropdown>;
}
function EffortPicker({ value, onChange }: { value: number; onChange: (value: number) => void }) {
  const [isOpen, setOpen] = useState(false);
  return <Dropdown isOpen={isOpen} onOpenChange={setOpen}>
    <DropdownTrigger aria-label={`Effort: ${EFFORT_LABELS[value]}`}
      className="pointer-events-auto relative flex shrink-0 cursor-pointer items-center rounded-full bg-background-tertiary-default py-1 pe-1 ps-2 outline-none transition-colors duration-150 ease hover:bg-background-tertiary-hover focus-visible:ring-2 focus-visible:ring-border-focus-ring">
      <span className="text-body-2-medium whitespace-nowrap text-text-secondary">{EFFORT_LABELS[value]}</span><RiArrowDownSLine aria-hidden className={cx("size-[18px] shrink-0 text-foreground-icon-secondary transition-transform duration-200 ease", isOpen ? "rotate-90" : "-rotate-90")} />
    </DropdownTrigger>
    <DropdownPopover aria-label="Effort" placement="bottom start" offset={8} className="w-[266px] p-1"
      dialogClassName="gap-0 pt-1">
      <EffortControl presentation="popover" value={value} onChange={onChange} />
    </DropdownPopover>
  </Dropdown>;
}

"use client";
import { useState } from "react";
import { RiGitMergeLine, RiRouteLine, RiShieldCheckLine, RiSpeedUpFill } from "@remixicon/react";
import { Button } from "../../base/buttons/button";
import { LinkButton } from "../../base/buttons/link-button";
import { Dropdown, DropdownPopover, DropdownTrigger } from "../../base/dropdown/dropdown";
import { cx } from "@/lib/cx";

export type ComposerPermission = "auto" | "manual" | "plan" | "bypass";
const PERMISSION_MODES = [
  { id: "auto", label: "Auto", description: "Agent decides by itself", Icon: RiSpeedUpFill },
  {
    id: "manual",
    label: "Manual",
    description: "Always ask before making a change",
    Icon: RiGitMergeLine,
  },
  {
    id: "plan",
    label: "Plan mode",
    description: "Create a plan before proceeding",
    Icon: RiRouteLine,
  },
  {
    id: "bypass",
    label: "Bypass all",
    description: "Agent handles permission decisions",
    Icon: RiShieldCheckLine,
  },
] as const;

export interface PermissionMenuProps {
  value: ComposerPermission;
  onChange: (value: ComposerPermission) => void;
  label?: string;
  learnMoreHref?: string;
  onLearnMore?: () => void;
}

/** Permission selection shared by compact and panel composers. */
export function PermissionMenu({ value, onChange, label, learnMoreHref, onLearnMore }: PermissionMenuProps) {
  const [permissionOpen, setPermissionOpen] = useState(false);
  const selectedPermission = value;
  const permissionMode = PERMISSION_MODES.find((mode) => mode.id === value) ?? PERMISSION_MODES[0];
  const permissionText = label ?? permissionMode.label;
  const PermissionIcon = permissionMode.Icon;
  return (
    <Dropdown isOpen={permissionOpen} onOpenChange={setPermissionOpen}>
      <DropdownTrigger
        aria-label={`Permission: ${permissionText}`}
        className={cx(
          "flex h-[30px] shrink-0 items-center gap-1 rounded-full py-[5px] pe-2.5 ps-2 outline-none transition-colors duration-150 ease hover:bg-background-primary-hover data-[pressed]:bg-background-primary-hover data-[focus-visible]:bg-background-primary-hover",
          permissionOpen && "bg-background-primary-hover",
        )}
      >
        <PermissionIcon
          className={cx(
            "size-4 shrink-0 text-foreground-icon-secondary",
            (selectedPermission === "manual" || selectedPermission === "plan") && "-scale-y-100",
          )}
        />
        <span className="text-body-medium whitespace-nowrap text-text-secondary">
          {permissionText}
        </span>
      </DropdownTrigger>
      <DropdownPopover
        aria-label="Permissions"
        placement="top start"
        offset={8}
        className="w-[323px] rounded-[20px] p-1.5"
        dialogClassName="gap-1.5 pt-1"
      >
        <div className="flex items-center gap-2.5 px-2 text-body-medium text-text-tertiary">
          <span className="min-w-0 flex-1">Permissions</span>
          <LinkButton
            {...(learnMoreHref ? { href: learnMoreHref } : {})}
            onClick={onLearnMore}
            variant="secondary"
            className="shrink-0 text-text-tertiary"
          >
            Learn more
          </LinkButton>
        </div>
        <div role="radiogroup" aria-label="Permission mode" className="flex flex-col gap-1">
          {PERMISSION_MODES.map(({ id, label, description, Icon }) => (
            <Button
              key={id}
              unstyled
              role="radio"
              aria-checked={id === selectedPermission}
              onClick={() => {
                onChange(id);
                setPermissionOpen(false);
              }}
              className={cx(
                "flex w-full cursor-pointer items-center gap-2 rounded-[14px] p-2 text-start outline-none transition-colors",
                id === selectedPermission
                  ? "bg-background-primary-hover"
                  : "hover:bg-background-primary-hover focus-visible:bg-background-primary-hover",
              )}
            >
              <Icon
                className={cx(
                  "size-5 shrink-0 text-foreground-icon-secondary",
                  (id === "manual" || id === "plan") && "-scale-y-100",
                )}
              />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-body-medium text-text-secondary">{label}</span>
                <span className="truncate text-body-2-medium text-text-tertiary">
                  {description}
                </span>
              </span>
            </Button>
          ))}
        </div>
      </DropdownPopover>
    </Dropdown>
  );
}

