"use client";
import { useEffect, useRef } from "react";

function noise(value: number) {
  const cell = Math.floor(value), t = value - cell;
  const hash = (n: number) => Math.sin(n * 127.1 + 311.7) * 43758.5453 % 1;
  const a = hash(cell), b = hash(cell + 1);
  return a + (b - a) * t * t * (3 - 2 * t);
}

/** Independently drawn star drift and blue exhaust for the effort track. */
export function EffortMaxField() {
  const starsRef = useRef<HTMLCanvasElement>(null);
  const jetRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const starsCanvas = starsRef.current, jetCanvas = jetRef.current;
    if (!starsCanvas || !jetCanvas || typeof CanvasRenderingContext2D === "undefined") return;
    const stars = starsCanvas.getContext("2d"), jet = jetCanvas.getContext("2d");
    if (!stars || !jet) return;
    const particles = Array.from({ length: 56 }, () => ({ x: Math.random(), y: Math.random(), depth: Math.random() }));
    let width = 0, height = 0, frame = 0;
    const born = performance.now();
    const resize = () => {
      const rect = starsCanvas.getBoundingClientRect();
      width = rect.width; height = rect.height;
      const ratio = Math.min(2, window.devicePixelRatio || 1);
      for (const canvas of [starsCanvas, jetCanvas]) {
        canvas.width = Math.max(1, Math.round(width * ratio));
        canvas.height = Math.max(1, Math.round(height * ratio));
      }
      stars.setTransform(ratio, 0, 0, ratio, 0, 0);
      jet.setTransform(ratio, 0, 0, ratio, 0, 0);
    };
    const draw = (now: number) => {
      if (document.hidden) { frame = 0; return; }
      const age = (now - born) / 1000;
      stars.clearRect(0, 0, width, height);
      jet.clearRect(0, 0, width, height);
      if (width > 0 && height > 0) {
        for (const particle of particles) {
          const speed = 35 + particle.depth * 100;
          const x = ((particle.x * (width + 8) - age * speed) % (width + 8) + width + 8) % (width + 8) - 4;
          stars.fillStyle = `rgba(255,255,255,${0.08 + particle.depth * 0.52})`;
          stars.fillRect(x, particle.y * height, 0.6 + particle.depth * 2.4, 0.5 + particle.depth * 0.45);
        }
        const head = width - 10.5;
        const length = width * 0.8 * (1 - Math.exp(-age / 0.4)) * (0.94 + 0.06 * Math.sin(age * 1.4));
        const center = height / 2;
        const trace = (scale: number) => {
          jet.beginPath();
          for (const side of [-1, 1]) {
            for (let i = 0; i <= 48; i++) {
              const position = side === -1 ? i / 48 : 1 - i / 48;
              const x = head - length + position * length;
              const flutter = noise(position * 6 - age * 5) * height * 0.045 * (1 - position);
              const radius = Math.pow(position, 0.55) * height * 0.34 * scale;
              const edge = noise(position * 20 - age * 9 + side * 13) * height * 0.055 * (1 - position) * scale;
              const y = center + flutter + side * (radius + edge);
              if (side === -1 && i === 0) jet.moveTo(x, y); else jet.lineTo(x, y);
            }
          }
          jet.closePath();
        };
        const flame = jet.createLinearGradient(head - length, center, head, center);
        flame.addColorStop(0, "rgba(81,162,255,0)");
        flame.addColorStop(0.12, "rgba(81,162,255,0.85)");
        flame.addColorStop(0.3, "#51a2ff");
        flame.addColorStop(1, "#51a2ff");
        trace(1); jet.fillStyle = flame; jet.fill();
        jet.strokeStyle = "rgba(59,130,246,0.85)"; jet.lineWidth = 1.25; jet.stroke();
        const core = jet.createLinearGradient(head - length, center, head, center);
        core.addColorStop(0, "rgba(185,219,255,0)");
        core.addColorStop(0.12, "rgba(185,219,255,0.3)");
        core.addColorStop(0.45, "#b9dbff");
        core.addColorStop(1, "#b9dbff");
        trace(0.7); jet.fillStyle = core; jet.fill();
      }
      frame = requestAnimationFrame(draw);
    };
    const visibility = () => {
      if (document.hidden) { cancelAnimationFrame(frame); frame = 0; }
      else if (!frame) frame = requestAnimationFrame(draw);
    };
    const observer = new ResizeObserver(resize);
    observer.observe(starsCanvas);
    resize();
    frame = requestAnimationFrame(draw);
    document.addEventListener("visibilitychange", visibility);
    return () => { cancelAnimationFrame(frame); observer.disconnect(); document.removeEventListener("visibilitychange", visibility); };
  }, []);
  return <>
    <div className="absolute inset-0 rounded-lg" style={{ background: "rgba(16,24,40,0.62)" }} />
    <canvas ref={starsRef} aria-hidden="true" className="absolute inset-0 size-full" />
    <canvas ref={jetRef} aria-hidden="true" className="absolute inset-0 size-full" />
  </>;
}
